BEGIN TRY
  BEGIN TRAN;
  UPDATE Documents SET UpdatedAt = SYSUTCDATETIME() WHERE Id = @Id;
  UPDATE DocumentItems SET IsValidated = 1 WHERE DocumentId = @Id;
  COMMIT;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0 ROLLBACK;
  THROW;
END CATCH;

var seen = new HashSet<int>();
var result = new List<int>();
foreach (var value in values) if (seen.Add(value)) result.Add(value);
return result;

if (size <= 0) throw new ArgumentOutOfRangeException(nameof(size));
var chunk = new List<T>(size);
foreach (var value in values) {
  chunk.Add(value);
  if (chunk.Count == size) { yield return chunk; chunk = new List<T>(size); }
}
if (chunk.Count > 0) yield return chunk;
